from __future__ import annotations

from join_link_resolver import effective_join_href, passcode_token_from_effective
from join_models import MeetingJoinProfile, StoredCalendarLink, embedded_differs_from_active
from join_uri_codec import read_query_param


def summarize_link_batch(profile: MeetingJoinProfile, links: list[StoredCalendarLink]) -> dict[str, object]:
    effective_hrefs: list[str] = []
    stale_embedded = 0
    mismatches_after_merge = 0

    for link in links:
        if embedded_differs_from_active(link, profile):
            stale_embedded += 1
        eff = effective_join_href(profile, link)
        effective_hrefs.append(eff)
        merged = passcode_token_from_effective(eff)
        if merged != profile.active_passcode:
            mismatches_after_merge += 1

    return {
        "link_count": len(links),
        "stale_embedded_passcodes": stale_embedded,
        "effective_hrefs": effective_hrefs,
        "resolver_mismatch_count": mismatches_after_merge,
        "profile_serial": profile.passcode_serial,
        "current_passcode": profile.active_passcode,
    }


def audit_headline(summary: dict[str, object]) -> str:
    return f"links={summary['link_count']};stale={summary['stale_embedded_passcodes']}"


def any_embedded_present(links: list[StoredCalendarLink]) -> bool:
    return any(str(link.embedded_passcode).strip() for link in links)


def collect_query_keys(href: str) -> set[str]:
    from join_uri_codec import clone_query

    return {k for k, _ in clone_query(href)}


def effective_still_missing_pwd(profile: MeetingJoinProfile, link: StoredCalendarLink) -> bool:
    eff = effective_join_href(profile, link)
    return read_query_param(eff, "pwd") in (None, "")


def compression_hint(summary: dict[str, object]) -> float:
    if summary["link_count"] == 0:
        return 1.0
    return round(summary["stale_embedded_passcodes"] / summary["link_count"], 3)


def filter_stale_links(profile: MeetingJoinProfile, links: list[StoredCalendarLink]) -> list[StoredCalendarLink]:
    return [link for link in links if embedded_differs_from_active(link, profile)]


def batch_serial_echo(profile: MeetingJoinProfile) -> str:
    return f"v{profile.passcode_serial}:{profile.meeting_number}"


def empty_batch_stub(profile: MeetingJoinProfile) -> dict[str, object]:
    return summarize_link_batch(profile, [])


def stale_link_ids(profile: MeetingJoinProfile, links: list[StoredCalendarLink]) -> list[str]:
    return [link.link_id for link in filter_stale_links(profile, links)]


def resolver_cleanliness_ok(summary: dict[str, object]) -> bool:
    return int(summary["resolver_mismatch_count"]) == 0


def rotation_signal_strength(summary: dict[str, object]) -> str:
    stale = int(summary["stale_embedded_passcodes"])
    total = int(summary["link_count"])
    if total == 0:
        return "noop"
    if stale == 0:
        return "aligned"
    if stale == total:
        return "all_stale"
    return "mixed"


def join_audit_tuple(profile: MeetingJoinProfile, link: StoredCalendarLink) -> tuple[str, str, str]:
    eff = effective_join_href(profile, link)
    tok = passcode_token_from_effective(eff) or ""
    return link.link_id, link.embedded_passcode, tok


def explain_summary_footer(summary: dict[str, object]) -> str:
    return f"serial={summary['profile_serial']};mismatch={summary['resolver_mismatch_count']}"

