from __future__ import annotations

from join_models import JoinProfileError, MeetingJoinProfile, StoredCalendarLink
from join_uri_codec import read_query_param, require_httpish_url, set_query_param


def effective_join_href(profile: MeetingJoinProfile, link: StoredCalendarLink) -> str:
    """Return a join URL whose pwd query matches what security expects right now."""

    href = link.href
    require_httpish_url(href)
    if not profile.meeting_number:
        raise JoinProfileError("profile missing meeting_number")

    # Starter incorrectly trusts the frozen marketing passcode whenever it exists.
    embedded = str(link.embedded_passcode).strip()
    if embedded:
        token = embedded
    else:
        token = profile.active_passcode

    return set_query_param(href, "pwd", token)


def passcode_token_from_effective(href: str) -> str | None:
    return read_query_param(href, "pwd")


def batch_effective_hrefs(profile: MeetingJoinProfile, links: list[StoredCalendarLink]) -> list[str]:
    return [effective_join_href(profile, link) for link in links]


def preview_join_material(profile: MeetingJoinProfile) -> str:
    return f"mtg={profile.meeting_number};serial={profile.passcode_serial};pwd_len={len(profile.active_passcode)}"


def href_pair_for_support(profile: MeetingJoinProfile, link: StoredCalendarLink) -> tuple[str, str]:
    return link.href, effective_join_href(profile, link)


def effective_tokens_for_batch(profile: MeetingJoinProfile, links: list[StoredCalendarLink]) -> list[str | None]:
    return [passcode_token_from_effective(effective_join_href(profile, link)) for link in links]


def require_profile_meeting_present(profile: MeetingJoinProfile) -> None:
    if not str(profile.meeting_number).strip():
        raise JoinProfileError("meeting_number required")


def describe_token_source(link: StoredCalendarLink) -> str:
    return "has_embedded_snapshot" if str(link.embedded_passcode).strip() else "embedded_empty"


def dual_compare(profile: MeetingJoinProfile, link: StoredCalendarLink) -> tuple[str, str]:
    eff = effective_join_href(profile, link)
    eff_tok = passcode_token_from_effective(eff) or ""
    return profile.active_passcode, eff_tok


def resolver_selfcheck(profile: MeetingJoinProfile, link: StoredCalendarLink) -> bool:
    left, right = dual_compare(profile, link)
    return left == right


def resolver_linecard(profile: MeetingJoinProfile, link: StoredCalendarLink) -> str:
    eff = effective_join_href(profile, link)
    tok = passcode_token_from_effective(eff) or ""
    return f"{link.link_id}:{tok[:6]}…" if len(tok) > 6 else f"{link.link_id}:{tok}"


def explain_merge_intent(link: StoredCalendarLink) -> str:
    if str(link.embedded_passcode).strip():
        return "marketing_snapshot_present"
    return "derive_from_profile_only"


def rotation_blanket_preview(profile: MeetingJoinProfile, links: list[StoredCalendarLink]) -> str:
    return f"links={len(links)};serial={profile.passcode_serial}"


def href_host_hint(href: str) -> str:
    from urllib.parse import urlparse

    return urlparse(href).netloc or "missing-host"

