from __future__ import annotations

from dataclasses import dataclass


class JoinProfileError(ValueError):
    """Invalid join profile or calendar link invariants."""


@dataclass
class MeetingJoinProfile:
    """Authoritative meeting join material as seen after admin console updates."""

    meeting_number: str
    active_passcode: str
    passcode_serial: int = 1

    def __post_init__(self) -> None:
        mid = str(self.meeting_number).strip()
        if not mid:
            raise JoinProfileError("meeting_number required")
        pwd = str(self.active_passcode).strip()
        if not pwd:
            raise JoinProfileError("active_passcode required")
        if self.passcode_serial < 1:
            raise JoinProfileError("passcode_serial must be >= 1")
        self.meeting_number = mid
        self.active_passcode = pwd


@dataclass(frozen=True)
class StoredCalendarLink:
    """A href captured when someone published a calendar attachment or web snippet."""

    link_id: str
    href: str
    embedded_passcode: str

    def __post_init__(self) -> None:
        lid = str(self.link_id).strip()
        if not lid:
            raise JoinProfileError("link_id required")
        url = str(self.href).strip()
        if not url:
            raise JoinProfileError("href required")
        object.__setattr__(self, "link_id", lid)
        object.__setattr__(self, "href", url)


def refresh_profile_passcode(profile: MeetingJoinProfile, new_passcode: str) -> None:
    token = str(new_passcode).strip()
    if not token:
        raise JoinProfileError("new_passcode required")
    if token == profile.active_passcode:
        return
    profile.active_passcode = token
    profile.passcode_serial += 1


def profile_signature(profile: MeetingJoinProfile) -> str:
    return f"{profile.meeting_number}:{profile.passcode_serial}"


def link_row_label(link: StoredCalendarLink) -> str:
    return f"{link.link_id}:{link.href[:24]}..." if len(link.href) > 24 else f"{link.link_id}:{link.href}"


def embedded_differs_from_active(link: StoredCalendarLink, profile: MeetingJoinProfile) -> bool:
    emb = str(link.embedded_passcode).strip()
    if not emb:
        return False
    return emb != profile.active_passcode


def describe_rotation(from_serial: int, to_serial: int) -> str:
    return f"serial {from_serial}->{to_serial}"


def clone_profile_stub(number: str, pwd: str, serial: int = 1) -> MeetingJoinProfile:
    """Convenience for tests that need a fresh profile object."""

    return MeetingJoinProfile(number, pwd, serial)


def join_material_tuple(profile: MeetingJoinProfile) -> tuple[str, str, int]:
    return profile.meeting_number, profile.active_passcode, profile.passcode_serial


def validate_meeting_digits_preview(value: str) -> bool:
    return str(value).strip().isdigit()

