from __future__ import annotations

from urllib.parse import parse_qsl, urlencode, urlparse, urlunparse

from join_models import JoinProfileError


def require_httpish_url(href: str) -> None:
    parsed = urlparse(href)
    if not parsed.scheme or not parsed.netloc:
        raise JoinProfileError("href must include scheme and host")


def extract_query_tuples(href: str) -> tuple[str, list[tuple[str, str]]]:
    require_httpish_url(href)
    parsed = urlparse(href)
    pairs = parse_qsl(parsed.query, keep_blank_values=True)
    return href, list(pairs)


def set_query_param(href: str, key: str, value: str) -> str:
    parsed = urlparse(href)
    pairs = parse_qsl(parsed.query, keep_blank_values=True)
    filtered = [(k, v) for k, v in pairs if k != key]
    filtered.append((key, value))
    new_query = urlencode(filtered)
    return urlunparse((parsed.scheme, parsed.netloc, parsed.path, parsed.params, new_query, parsed.fragment))


def read_query_param(href: str, key: str) -> str | None:
    parsed = urlparse(href)
    pairs = parse_qsl(parsed.query, keep_blank_values=True)
    for k, v in pairs:
        if k == key:
            return v
    return None


def strip_credentials_for_compare(href: str) -> str:
    parsed = urlparse(href)
    pairs = [(k, v) for k, v in parse_qsl(parsed.query, keep_blank_values=True) if k != "pwd"]
    new_query = urlencode(pairs)
    return urlunparse((parsed.scheme, parsed.netloc, parsed.path, parsed.params, new_query, parsed.fragment))


def path_tail_segments(href: str) -> list[str]:
    parsed = urlparse(href)
    trimmed = parsed.path.strip("/")
    if not trimmed:
        return []
    return [seg for seg in trimmed.split("/") if seg]


def join_path_preview(href: str, max_segments: int = 3) -> str:
    segs = path_tail_segments(href)[:max_segments]
    return "/".join(segs)


def ensure_scheme_lower(href: str) -> str:
    parsed = urlparse(href)
    if not parsed.scheme:
        raise JoinProfileError("scheme required")
    scheme = parsed.scheme.lower()
    return urlunparse((scheme, parsed.netloc, parsed.path, parsed.params, parsed.query, parsed.fragment))


def clone_query(href: str) -> list[tuple[str, str]]:
    parsed = urlparse(href)
    return list(parse_qsl(parsed.query, keep_blank_values=True))


def merge_query_preserving_order(href: str, updates: dict[str, str]) -> str:
    parsed = urlparse(href)
    pairs = parse_qsl(parsed.query, keep_blank_values=True)
    as_dict = dict(pairs)
    as_dict.update(updates)
    ordered_keys = [k for k, _ in pairs] + [k for k in updates if k not in dict(pairs)]
    seen: set[str] = set()
    out_pairs: list[tuple[str, str]] = []
    for k in ordered_keys:
        if k in seen:
            continue
        seen.add(k)
        if k in as_dict:
            out_pairs.append((k, as_dict[k]))
    for k, v in as_dict.items():
        if k not in seen:
            out_pairs.append((k, v))
    new_query = urlencode(out_pairs)
    return urlunparse((parsed.scheme, parsed.netloc, parsed.path, parsed.params, new_query, parsed.fragment))


def href_fingerprint(href: str) -> str:
    p = urlparse(href)
    return f"{p.netloc}:{p.path}:q={len(parse_qsl(p.query))}"

